import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  success: '#10B981',
  danger: '#EF4444',
  primary: '#6366F1',
  surface: '#F8FAFC',
  text: '#1E293B'
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const isProcessingRef = useRef(false);

  // States
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [timeLeft, setTimeLeft] = useState(10);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [capturedImg, setCapturedImg] = useState(null);
  const [error, setError] = useState(null);

  // 1. Démarrer/Arrêter la caméra
  const toggleCamera = async () => {
    if (isCameraOpen) {
      stopCamera();
    } else {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user', width: 1280, height: 720 }
        });
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setIsCameraOpen(true);
        setTimeLeft(10);
        setResult(null);
        setCapturedImg(null);
      } catch (err) {
        addNotification("Erreur caméra", "error");
      }
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    setIsCameraOpen(false);
    setTimeLeft(0);
  };

  // 2. Logique du compte à rebours et détection auto
  useEffect(() => {
    let timer;
    let detectionInterval;

    if (isCameraOpen && timeLeft > 0 && !result) {
      // Décompte
      timer = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);

      // Tentative de détection toutes les 800ms
      detectionInterval = setInterval(async () => {
        if (isProcessingRef.current) return;
        await autoCapture();
      }, 800);
    } 

    if (timeLeft === 0 && isCameraOpen && !result) {
      addNotification("Temps écoulé - Aucun visage détecté", "warning");
      stopCamera();
    }

    return () => {
      clearInterval(timer);
      clearInterval(detectionInterval);
    };
  }, [isCameraOpen, timeLeft, result]);

  // 3. Fonction de capture
  const autoCapture = async () => {
    if (!videoRef.current || isProcessingRef.current) return;

    const canvas = document.createElement('canvas');
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(videoRef.current, 0, 0);

    const base64 = canvas.toDataURL('image/jpeg', 0.8);

    try {
      isProcessingRef.current = true;
      const res = await attendanceAPI.recognize(base64);

      if (res.data.success) {
        setCapturedImg(base64); // On garde l'image du direct
        setResult(res.data);
        addNotification(`${res.data.student} détecté !`, 'success');
        stopCamera(); // On arrête la caméra dès qu'on trouve
      }
    } catch (err) {
      console.warn("Scan en cours...");
    } finally {
      isProcessingRef.current = false;
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>👤 Vérification d'Identité IA</h2>

        {/* VIEWPORT CAMERA */}
        <div style={styles.cameraWrapper}>
          <video ref={videoRef} autoPlay playsInline muted style={styles.video} />

          {!isCameraOpen && !result && (
            <div style={styles.overlay}>
              <button onClick={toggleCamera} style={styles.startBtn}>
                📸 Ouvrir la Caméra
              </button>
            </div>
          )}

          {isCameraOpen && (
            <div style={styles.timerBadge}>
              ⏱️ Scan actif: {timeLeft}s
            </div>
          )}
        </div>

        {/* SECTION COMPARAISON (CÔTE À CÔTE) */}
        {result && (
          <div style={styles.comparisonContainer}>
            <div style={styles.matchHeader}>
              <div style={styles.matchScore}>
                Score de correspondance: {(result.confidence * 100).toFixed(1)}%
              </div>
            </div>

            <div style={styles.sideBySide}>
              {/* IMAGE CAPTURÉE */}
              <div style={styles.imgBox}>
                <p style={styles.imgLabel}>Capture Direct</p>
                <img src={capturedImg} alt="Capture" style={styles.faceImg} />
              </div>

              <div style={styles.vsIcon}>⚡</div>

              {/* IMAGE DE RÉFÉRENCE (DATABASE) */}
              <div style={styles.imgBox}>
                <p style={styles.imgLabel}>Référence Base de données</p>
                {/* On suppose que ton backend renvoie l'URL de la photo d'enrôlement */}
                <div style={styles.refPlaceholder}>
                   <img 
                    src={result.enrollment_photo || "https://via.placeholder.com/150?text=Photo+Ref"} 
                    alt="Référence" 
                    style={styles.faceImg} 
                   />
                </div>
              </div>
            </div>

            <div style={styles.infoFooter}>
              <h3 style={{color: COLORS.success, margin: '0 0 5px 0'}}>{result.student}</h3>
              <p style={{margin: 0, fontSize: '0.9rem', color: '#666'}}>{result.email}</p>
              <p style={{margin: '10px 0 0 0', fontWeight: 'bold'}}>Statut: PRÉSENT ✅</p>
              <button onClick={() => {setResult(null); toggleCamera();}} style={styles.retryBtn}>
                Scanner une autre personne
              </button>
            </div>
          </div>
        )}

        {isCameraOpen && (
          <button onClick={stopCamera} style={styles.stopBtn}>Fermer</button>
        )}
      </div>
    </div>
  );
};

// ============ STYLES ============
const styles = {
  container: { padding: '20px', maxWidth: '1000px', margin: '0 auto' },
  card: { background: 'white', borderRadius: '20px', padding: '30px', boxShadow: '0 10px 30px rgba(0,0,0,0.1)' },
  title: { textAlign: 'center', marginBottom: '20px', color: COLORS.text },
  cameraWrapper: { 
    position: 'relative', 
    width: '100%', 
    height: '400px', 
    backgroundColor: '#000', 
    borderRadius: '15px', 
    overflow: 'hidden',
    marginBottom: '20px'
  },
  video: { width: '100%', height: '100%', objectFit: 'cover' },
  overlay: { 
    position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', 
    display: 'flex', justifyContent: 'center', alignItems: 'center', background: 'rgba(0,0,0,0.6)' 
  },
  timerBadge: {
    position: 'absolute', top: 20, right: 20, background: COLORS.danger, 
    color: 'white', padding: '8px 15px', borderRadius: '20px', fontWeight: 'bold'
  },
  startBtn: { 
    padding: '15px 30px', fontSize: '1.1rem', background: COLORS.primary, 
    color: 'white', border: 'none', borderRadius: '50px', cursor: 'pointer', fontWeight: 'bold' 
  },
  comparisonContainer: {
    marginTop: '20px', padding: '20px', border: `2px solid ${COLORS.success}`, borderRadius: '15px', background: '#F0FDF4'
  },
  sideBySide: { display: 'flex', alignItems: 'center', justifyContent: 'space-around', gap: '20px', margin: '20px 0' },
  imgBox: { flex: 1, textAlign: 'center' },
  imgLabel: { fontSize: '0.8rem', fontWeight: 'bold', color: '#666', marginBottom: '10px', textTransform: 'uppercase' },
  faceImg: { width: '100%', height: '200px', objectFit: 'cover', borderRadius: '10px', border: '3px solid white', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' },
  vsIcon: { fontSize: '1.5rem', fontWeight: 'bold', color: COLORS.primary },
  matchHeader: { textAlign: 'center' },
  matchScore: { background: COLORS.success, color: 'white', display: 'inline-block', padding: '5px 15px', borderRadius: '15px', fontWeight: 'bold' },
  infoFooter: { textAlign: 'center', borderTop: '1px solid #ddd', paddingTop: '15px' },
  retryBtn: { marginTop: '15px', padding: '10px 20px', background: COLORS.text, color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' },
  stopBtn: { width: '100%', padding: '10px', background: '#eee', border: 'none', borderRadius: '8px', cursor: 'pointer', color: '#666' }
};

export default CameraRecognition;
